package io.knowledgebrain.integration;
import java.util.*;import tools.jackson.databind.json.JsonMapper;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class GitHubWorkClientTest {
 final JsonMapper json=JsonMapper.builder().build();final GitHubClient.Repository repo=new GitHubClient.Repository("1296269","octocat/Hello-World","https://github.com/octocat/Hello-World","main");
 String raw(boolean pr){return "{\"id\":42,\"number\":7,\"title\":\"Safe title <img>\",\"state\":\"open\",\"user\":{\"login\":\"dependabot[bot]\"},\"created_at\":\"2020-01-01T00:00:00Z\",\"updated_at\":\"2020-01-02T00:00:00Z\",\"closed_at\":null,\"html_url\":\"https://github.com/octocat/Hello-World/"+(pr?"pull":"issues")+"/7\""+(pr?",\"draft\":true":"")+"}";}
 @Test void exactBoundedEndpointsAndExplicitIssuePrDistinction()throws Exception{var remote=mock(GitHubClient.class);var client=new GitHubWorkClient(remote);for(boolean pr:List.of(false,true)){String kind=pr?"PULL_REQUEST":"ISSUE",path="/repos/octocat/Hello-World/"+(pr?"pulls":"issues")+"?state=all&sort=updated&direction=desc&per_page=20";when(remote.get(path)).thenReturn(json.readTree("["+raw(pr)+"]"));var b=client.fetch(repo,kind);assertEquals(1,b.items().size());assertEquals("dependabot[bot]",b.items().getFirst().authorLogin());assertEquals(pr?true:null,b.items().getFirst().draft());verify(remote).get(path);}String issue=raw(false),pull=raw(true);pull=pull.substring(0,pull.length()-1)+",\"pull_request\":{\"url\":\"https://api.github.com/repos/octocat/Hello-World/pulls/7\"}}";var b=GitHubWorkClient.parse(repo,"ISSUE",json.readTree("["+issue+","+pull+"]"));assertEquals(2,b.scannedCount());assertEquals(1,b.items().size());}
 @Test void poisonedUrlsNumbersStateClockAndDuplicateFactsFailClosed()throws Exception{String valid=raw(true);for(String bad:List.of(valid.replace("/pull/7","/issues/7"),valid.replace("\"open\"","\"merged\""),valid.replace("\"number\":7","\"number\":1.5"),valid.replace("\"draft\":true","\"draft\":null"),valid.replace("2020-01-02","2019-01-02"),valid.replace("\"closed_at\":null","\"closed_at\":\"2020-01-02T00:00:00Z\""),valid.replace("dependabot[bot]","evil/actor"))){assertThrows(RuntimeException.class,()->GitHubWorkClient.parse(repo,"PULL_REQUEST",json.readTree("["+bad+"]")));}assertThrows(RuntimeException.class,()->GitHubWorkClient.parse(repo,"PULL_REQUEST",json.readTree("["+valid+","+valid+"]")));assertThrows(RuntimeException.class,()->GitHubWorkClient.parse(repo,"PULL_REQUEST",json.readTree("{}")));}
}
